// ❌ OLD: A divide-and-conquer sum that runs entirely on ONE thread.
// The recursion splits the problem but does not use the other cores,
// so on a 16-core machine 15 cores sit idle.
public class SumLegacy {
  static int sum(int[] a, int lo, int hi) {
    if (hi - lo < 1_000) {
      int s = 0;
      for (int i = lo; i < hi; i++) s += a[i];
      return s;
    }
    int mid = (lo + hi) / 2;
    // ❌ OLD: both halves run on this same thread, sequentially
    return sum(a, lo, mid) + sum(a, mid, hi);
  }

  public static void main(String[] args) {
    int[] a = new int[10_000_000];
    System.out.println(sum(a, 0, a.length)); // ❌ OLD: one core busy
  }
}

import java.util.stream.IntStream;

// ✅ NEW: A parallel stream splits the work via Spliterator and submits
// subtasks to the common ForkJoinPool, which balances load with
// work-stealing across all cores.
public class SumModern {
  public static void main(String[] args) {
    int[] a = new int[10_000_000];

    // ✅ NEW: parallel split + join on the common pool
    int total = IntStream.range(0, a.length)
        .parallel()
        .map(i -> a[i])
        .sum();

    System.out.println(total);

